ew.layer.masksToBounds = cell.layer.masksToBounds = YES;1、关于UITableView.UITableViewCell# 1.1、圆切角# 1.1.1、以section为单位，每个section的第一行和最后一行的cell圆角化处理【cell之间没有分割线】# /// 以section为单位，每个section的第一行和最后一行的cell圆角化处理【cell之间没有分割线】 -(__kindof CALayer *)roundedCornerFirstAndLastCellByTableView:(UITableView *)tableView indexPath:(NSIndexPath *)indexPath layerConfig:(JobsLocationModel *)layerConfig{ // 关闭分割线 tableView.separatorStyle = UITableViewCellSeparatorStyleNone; @jobs_weakify(self) if (jobsZeroSizeValue(layerConfig.roundingCornersRadii)) layerConfig.roundingCornersRadii = CGSizeMake(JobsWidth(10.0), JobsWidth(10.0)); // 当前 section 的总行数 NSInteger numberOfRows = tableView.rowsInSection(indexPath.section); // 初始化将要设置的圆角类型 UIRectCorner corner = 0; if (numberOfRows == 1) { corner = UIRectCornerAllCorners; } else if (indexPath.row == 0) { corner = UIRectCornerTopLeft | UIRectCornerTopRight; } else if (indexPath.row == numberOfRows - 1) { corner = UIRectCornerBottomLeft | UIRectCornerBottomRight; } else { // 中间 cell，无圆角和边框 self.layer.mask = nil; // 移除边框 Layer（避免复用残留） NSArray *sublayers = self.layer.sublayers.copy; for (CALayer *sublayer in sublayers) { if ([sublayer.name isEqualToString:@&#34;rounded-border-layer&#34;]) { [sublayer removeFromSuperlayer]; } }return self.layer; } // 设置圆角路径 UIBezierPath *maskPath = [UIBezierPath bezierPathWithRoundedRect:self.bounds byRoundingCorners:corner cornerRadii:layerConfig.roundingCornersRadii]; self.layer.mask = jobsMakeCAShapeLayer(^(__kindof CAShapeLayer * _Nullable layer) { @jobs_strongify(self) layer.frame = self.bounds; layer.path = maskPath.CGPath; }); // 添加边框 Layer（可选） if (layerConfig.layerBorderCor &amp;&amp; layerConfig.borderWidth &gt; 0) { // 移除之前旧的 border layer，避免复用叠加 NSArray *sublayers = self.layer.sublayers.copy; for (CALayer *sublayer in sublayers) { if ([sublayer.name isEqualToString:@&#34;rounded-border-layer&#34;]) { [sublayer removeFromSuperlayer]; } } self.layer.addSublayer(jobsMakeCAShapeLayer(^(__kindof CAShapeLayer * _Nul